        level: 'kiso',
        body: `方程式とは「未知数 x を含む等式」であり、それを成り立たせる x の値（解）を求めることが目標である。

■ 天秤モデルで理解する等式
方程式は天秤のように「左辺＝右辺」が成り立っている。両辺に同じ操作をすれば等式は維持される。

　　　左辺　　　　右辺
　　┌──────┐　　┌──────┐
　　│ 2x + 3 │＝│  11  │
　　└──────┘　　└──────┘
　　　　　　↓ 両辺から 3 を引く
　　┌──────┐　　┌──────┐
　　│  2x   │＝│   8  │
　　└──────┘　　└──────┘
　　　　　　↓ 両辺を 2 で割る
　　┌──────┐　　┌──────┐
　　│   x   │＝│   4  │
　　└──────┘　　└──────┘

■ 移項のルール
等式の一方の辺にある項を符号を変えて他方の辺に移すことを「移項」という。
　　ax + b = c　→　ax = c − b　→　x = (c − b) / a

■ 係数に分数・小数が含まれる場合
分数：両辺に分母の最小公倍数をかけて整数化する。
小数：両辺に 10・100 などをかけて整数化する。

例①　2x + 3 = 11
　2x = 11 − 3 = 8
　x = 4

例②　x/3 − 1 = 2
　両辺 × 3：x − 3 = 6
　x = 9

例③　0.4x + 1.2 = 2.8
　両辺 × 10：4x + 12 = 28
　4x = 16　→　x = 4

★ ポイント：「移項するたびに符号が逆になる」。これを忘れると計算ミスの原因になる。

⚠ 注意：x = ○ の形にしたら必ず元の方程式に代入して検証すること。代入確認は1点の差を生む。`,
