        heading: '5. 置き換えを使った展開・因数分解',
        level: 'moshi',
        body: `かたまりを 1 つの文字に「置き換える」と、複雑な式が公式で処理できる。

■ 置き換えの基本
共通するかたまりを A などとおく。
例）(x + y)² + 3(x + y) + 2
　x + y = A とおくと A² + 3A + 2 = (A + 1)(A + 2)
　A を戻す：(x + y + 1)(x + y + 2)

■ 差の 2 乗の組合せ
例）(a + b)² − (a − b)²
　X = a + b、Y = a − b とおくと X² − Y² = (X + Y)(X − Y)
　X + Y = 2a、X − Y = 2b
　= 2a × 2b = 4ab

■ 4 つの数の積 + 1（有名問題）
例）(x)(x + 1)(x + 2)(x + 3) + 1 を因数分解
　両端どうし・内側どうしを組む：
　{x(x+3)}{(x+1)(x+2)} + 1 = (x² + 3x)(x² + 3x + 2) + 1
　x² + 3x = A とおくと A(A + 2) + 1 = A² + 2A + 1 = (A + 1)²
　= (x² + 3x + 1)²

■ 展開の工夫（順序を選ぶ）
(x − 1)(x − 2)(x − 3)(x − 4) は
　{(x−1)(x−4)}{(x−2)(x−3)} = (x² − 5x + 4)(x² − 5x + 6)
　x² − 5x = A として (A + 4)(A + 6) と処理する。

★ ポイント：複雑な式は「同じかたまりを作れる組合せ」を探すのが勝負。両端どうし・内側どうしを組むと共通のかたまりが現れやすい。

⚠ 注意：置き換えた文字を最後に必ず元に戻す。A のまま答えると 0 点。「A = x + y を戻して…」と書く習慣を。`,
