        heading: '3. 分母の有理化',
        level: 'oyo',
        body: `分母に根号があるとき、分母から根号をなくすことを「有理化」という。

■ なぜ有理化するか
分母に √ があると値が求めにくい。分母を整数にすると計算・比較がしやすくなる。標準的な答えの形でもある。

■ 基本の有理化（分母が単項）
分母と分子に同じ根号をかける。
　1/√2 = (1 × √2)/(√2 × √2) = √2/2

例①　3/√5 = 3√5/5
例②　4/√8 = 4/(2√2) = 2/√2 = 2√2/2 = √2
　（先に √8 = 2√2 と簡約してから有理化すると楽）

■ 分母が 2 項（和・差）の有理化
分母が a + √b の形 → a − √b（共役）をかける。
　和と差の積 (a + √b)(a − √b) = a² − b で根号が消える。

例）1/(√3 + 1)
　= (√3 − 1) / {(√3 + 1)(√3 − 1)}
　= (√3 − 1) / (3 − 1)
　= (√3 − 1)/2

例）2/(√5 − √3)
　= 2(√5 + √3) / {(√5 − √3)(√5 + √3)}
　= 2(√5 + √3) / (5 − 3)
　= 2(√5 + √3)/2 = √5 + √3

★ ポイント：分母が 2 項のときは「符号だけ変えた共役」をかける。(a + b)(a − b) = a² − b² で根号が必ず消える。

⚠ 注意：有理化する前に分母を簡約できないか確認する。4/√8 はいきなり有理化するより √8 = 2√2 にしてからの方が数が小さく済む。`,
