        level: 'moshi',
        figureId: 'lf_kmath_22',
        body: `根号の大小比較や、整数部分・小数部分を扱う問題は入試で差がつく。

■ 大小の比較
根号を含む数の大小は「2 乗して比べる」または「a√b を √(a²b) に直して中身で比べる」。
例）2√3 と 3√2 の大小
　2√3 = √12、3√2 = √18 → √12 < √18 → 2√3 < 3√2

■ 整数を根号に直して比較
例）√10 と 3 の大小
　3 = √9、√9 < √10 → 3 < √10

■ 整数部分・小数部分
√a の整数部分 n は「n² ≤ a < (n+1)²」を満たす n。
小数部分 = √a − n

例）√7 の整数部分と小数部分
　2² = 4 ≤ 7 < 9 = 3² → 整数部分は 2
　小数部分 = √7 − 2

例）√7 の小数部分を a とするとき a(a + 4) の値
　a = √7 − 2
　a + 4 = √7 + 2
　a(a + 4) = (√7 − 2)(√7 + 2) = 7 − 4 = 3

■ 近似値の利用
　√2 ≒ 1.41、√3 ≒ 1.73 を使って値を概算する。
例）√12 = 2√3 ≒ 2 × 1.73 = 3.46

■ 根号が整数になる条件
例）√(24n) が整数になる最小の自然数 n
　24 = 2³ × 3 → √(2³ × 3 × n) が整数になるには不足の素因数を補う
　2³×3 を平方にするには 2×3 = 6 が必要 → n = 6
　（このとき √(24×6) = √144 = 12）

★ ポイント：「√(整数×n) を整数にする最小の n」は、根号の中を素因数分解し、指数が奇数の素因数を 1 つずつ補えばよい。

⚠ 注意：√a の整数部分を求めるとき、a に近い平方数を上下から挟む。√50 なら 49 = 7² と 64 = 8² で挟んで整数部分 7。

📝 入試問題例
√5 の整数部分を a、小数部分を b とするとき、a² + b(b + 4) の値を求めよ。
　2² = 4 ≤ 5 < 9 → a = 2、b = √5 − 2
　b + 4 = √5 + 2
　b(b + 4) = (√5 − 2)(√5 + 2) = 5 − 4 = 1
　a² + b(b + 4) = 4 + 1 = 5`,
