        body: `立体を平面で表す 3 つの方法を読み書きできるようにする。

■ 3 つの表し方
　・見取図：立体を斜めから見た図（立体らしく見える）
　・展開図：立体を切り開いて平面にした図
　・投影図：真正面（立面図）と真上（平面図）から見た図

■ 投影図の読み方
　立面図（正面から）＋ 平面図（真上から）で立体を特定する。
　　立面図が長方形・平面図が円 → 円柱
　　立面図が三角形・平面図が円 → 円錐
　　立面図が三角形・平面図が三角形 → 三角錐 など

ASCII 例（円柱の投影図）
　立面図　　平面図
　┌───┐　　 ○
　│   │　　（円）
　└───┘

■ 展開図の要点
　・円柱の側面 → 長方形（横 = 底面の円周 2πr）
　・円錐の側面 → おうぎ形（半径 = 母線 l、弧 = 底面の円周 2πr）
　・角柱の側面 → 長方形が並ぶ

■ 円錐の展開図の中心角
おうぎ形の弧 = 底面の円周 だから
　中心角 = 360° ×(底面半径 r)/(母線 l)

例）母線 6cm、底面半径 2cm の円錐
　中心角 = 360° × 2/6 = 120°

★ ポイント：円錐の展開図では「側面のおうぎ形の弧の長さ = 底面の円の周の長さ」。この 1 本の等式ですべての計算がつながる。

⚠ 注意：立方体の展開図は 11 種類ある。組み立てたとき向かい合う面（対面）がどこになるかを、頭の中で折りたたんで確認する。`,
