        body: `平面図形を回転させてできる立体や、立体を組み合わせた図形は入試の花形。

■ 回転体とは
平面図形を 1 つの直線（回転軸）のまわりに 1 回転させてできる立体。
　・長方形 → 円柱
　・直角三角形 → 円錐
　・半円 → 球
　・台形（直角台形）→ 円錐台や複合立体

■ 回転体の見取図の例
直角三角形（底辺 3・高さ 4）を高さの辺を軸に回転
　→ 底面半径 3、高さ 4 の円錐

■ 複合立体の体積（分けて足す・引く）
例）円柱の上に円錐が乗った立体
　全体 = 円柱の体積 + 円錐の体積

例）大きな円錐から小さな円錐を切り取った「円錐台」
　円錐台 = 大円錐 − 小円錐

■ 立体の切断
立方体を平面で切ると、切り口は三角形・四角形・五角形・六角形になる。
　・3 つの辺を通る → 三角形
　・向かい合う辺を通る → 長方形やひし形
　・6 つの面すべてを横切る → 六角形

■ 展開図上の最短距離（三平方と融合）
立体の表面をひもが這う最短距離は「展開図を開いて直線で結ぶ」。
例）円柱の側面を 1 周するひもの最短 → 側面の長方形（横 2πr、縦 h）の対角線 √((2πr)² + h²)

■ 回転体・複合立体の解法手順
┌──────────────────────────────────────┐
│ ① もとの平面図形と回転軸を確認する              │
│ ② できる立体（円柱・円錐・球・円錐台）を特定    │
│ ③ 立体ごとに体積・表面積を計算して足す／引く    │
│ ④ 表面積では「くっつく面」を数えない            │
└──────────────────────────────────────┘

★ ポイント：複合立体の表面積では、2 つの立体が接する面は「外に出ない」ので数えない。体積は単純に足せるが、表面積は接合面に注意。

⚠ 注意：回転軸に接していない図形を回転させると、中央に穴の空いた立体（ドーナツ状や、くり抜かれた円柱）になる。軸と図形の位置関係をよく見る。

📝 入試問題例
底面の半径 3cm、高さ 4cm の円錐がある。この円錐の体積・母線の長さ・表面積を求めよ。
　体積 = (1/3)π × 3² × 4 = 12π cm³
　母線 l = √(3² + 4²) = √25 = 5cm
　表面積 = 底面 π×3² + 側面 π×5×3 = 9π + 15π = 24π cm²`,
