        level: 'moshi',
        figureId: 'lf_kmath_28',
        body: `2 つ以上の不等式を同時に満たす範囲を求めるのが連立不等式。

■ 連立不等式の解き方
　① それぞれの不等式を解く
　② 2 つの解の「共通部分（重なり）」を数直線で求める

例）次の連立不等式を解け
　　3x − 1 > 5　… ①
　　2x + 3 ≤ 11 … ②

　①：3x > 6 → x > 2
　②：2x ≤ 8 → x ≤ 4

　数直線で共通部分：
　　　　○───────●
　　　　2　　　　　4
　　→ 2 < x ≤ 4

■ 共通部分の考え方
　「①も②も成り立つ」＝ 両方の範囲が重なるところ
　　① x > 2 ：　　○────────→
　　② x ≤ 4 ：←────────●
　　共通　　：　　○────●（2 < x ≤ 4）

■ A < B < C の形
　A < B < C は「A < B かつ B < C」の連立とみなす。
例）1 < 2x − 3 < 7
　1 < 2x − 3 かつ 2x − 3 < 7
　→ 4 < 2x かつ 2x < 10
　→ 2 < x かつ x < 5
　→ 2 < x < 5

■ 解がない場合
2 つの範囲が重ならないとき、連立不等式の解は「なし」。
例）x > 5 かつ x < 3 → 共通部分なし → 解なし

★ ポイント：連立不等式は「数直線を必ず書く」。頭の中だけで共通部分を判断すると、端の値（= を含むか）を間違えやすい。

⚠ 注意：A < B < C 型では、まん中の B（x を含む式）を両側と比べる。「1 < 7」のように x を含まない部分だけで判断しない。

📝 入試問題例
連立不等式 5x + 2 ≥ 3x − 4、4 − x > 1 を満たす整数 x をすべて求めよ。
　① 5x + 2 ≥ 3x − 4 → 2x ≥ −6 → x ≥ −3
　② 4 − x > 1 → −x > −3 → x < 3
　共通：−3 ≤ x < 3 → 整数 x = −3, −2, −1, 0, 1, 2`,
