        body: `文章題は「何を x とおくか」を決め、条件を不等式で表すのがカギ。

■ 手順
　① 求めたい量を x とおく
　② 「以上・以下・未満・より多い」の条件を不等式にする
　③ 不等式を解き、条件（整数・正の数など）で答えを絞る

■ 個数を求める文章題
例）1 個 120 円のケーキと 1 個 80 円のプリンを合わせて 10 個買い、代金を 1000 円以下にしたい。ケーキを最大何個買えるか。
　ケーキ x 個、プリン (10 − x) 個とする。
　120x + 80(10 − x) ≤ 1000
　120x + 800 − 80x ≤ 1000
　40x ≤ 200
　x ≤ 5
　→ ケーキは最大 5 個

■ 「〜するとおつりが出る」型
例）1 本 150 円のペンを何本か買って 1000 円札で払うとおつりが出る。最大何本？
　150x < 1000
　x < 6.66…
　x は整数なので x ≤ 6 → 最大 6 本

■ 平均・得点の文章題
例）3 回のテストの平均を 80 点以上にしたい。1 回目 75 点、2 回目 82 点。3 回目は何点以上必要か。
　(75 + 82 + x)/3 ≥ 80
　157 + x ≥ 240
　x ≥ 83 → 83 点以上

■ 文章題での不等号の選び方
┌──────────────────┬────────┐
│ 「〜以下」「〜を超えない」  │ ≤       │
│ 「〜以上」「少なくとも」    │ ≥       │
│ 「〜未満」「〜より少ない」  │ <       │
│ 「〜より多い」「〜を超える」│ >       │
└──────────────────┴────────┘

★ ポイント：答えを出したら「整数か」「正の数か」「実際の場面に合うか」で必ず吟味する。x ≤ 5.5 なら整数解は 5 まで、と現実に即して答える。

⚠ 注意：「1000 円以下」は ≤（1000 を含む）、「おつりが出る＝1000 円未満」は <（1000 を含まない）。日本語を不等号に正確に翻訳する。`,
