        level: 'kiso',
        figureId: 'lf_kmath_30',
        body: `平面図形の言葉と、定規・コンパスによる基本作図を確実にする。

■ 基本用語
　・線分：2 点を結ぶまっすぐな線（両端がある）
　・直線：どこまでも伸びる線（両端がない）
　・半直線：一方だけに伸びる線
　・弧 AB：円周の一部　・弦 AB：円周上の 2 点を結ぶ線分
　・中心角：おうぎ形の 2 本の半径がつくる角

■ 3 つの基本作図（コンパスと定規のみ）
① 垂直二等分線：線分 AB の両端から等しい半径の円をかき、交点 2 つを結ぶ
　→ 線分を垂直に 2 等分する。AB から等距離の点の集まり。
② 角の二等分線：頂点を中心に弧をかき、両辺との交点から等半径の弧をかいて交点を結ぶ
　→ 角を 2 等分する。角の 2 辺から等距離の点の集まり。
③ 垂線：直線上（外）の点から、その直線に垂直な線を引く

■ 垂直二等分線の図
　　　　×（交点）
　　　／│＼
　　A──┼──B
　　　＼│／
　　　　×（交点）
　2 つの交点を結ぶと AB の垂直二等分線

■ 作図でわかる「等距離の性質」
　・垂直二等分線上の点 → 線分の両端から等距離
　・角の二等分線上の点 → 角の 2 辺から等距離
　この性質は「点の位置を決める」問題（後述の軌跡）で使う。

★ ポイント：作図問題は「どんな点の集まりか」を意識する。「2 点から等距離＝垂直二等分線」「2 辺から等距離＝角の二等分線」がほぼすべての作図の土台。

⚠ 注意：作図では引いた線・弧（コンパスの跡）を消さない。採点では「作図の跡」も見られる。答えの線だけでなく補助の弧も残す。`,
