        level: 'oyo',
        figureId: 'lf_kmath_31',
        body: `円とおうぎ形の計量は「中心角が 360° の何分か」で考えるのが基本。

■ 円の周と面積（半径 r）
　円周 = 2π r
　面積 = π r²

■ おうぎ形（半径 r、中心角 a°）
　弧の長さ = 2π r × (a/360)
　面積　　 = π r² × (a/360)

■ 中心角と割合のイメージ
　中心角 90° → 円の 1/4（90/360）
　中心角 120° → 円の 1/3
　中心角 60° → 円の 1/6

例）半径 6cm、中心角 120° のおうぎ形
　弧の長さ = 2π × 6 × (120/360) = 12π × (1/3) = 4π cm
　面積 = π × 6² × (120/360) = 36π × (1/3) = 12π cm²

■ 弧の長さから面積を出す便利公式
　おうぎ形の面積 = (1/2) × 弧の長さ × 半径
　　S = (1/2) l r
（三角形の面積公式に似ている。弧を底辺、半径を高さのように扱える）

例）半径 6cm、弧 4π cm のおうぎ形
　面積 = (1/2) × 4π × 6 = 12π cm²（上と一致）

■ 中心角を求める
例）半径 5cm、弧の長さ 2π cm のおうぎ形の中心角
　2π = 2π × 5 × (a/360)
　2π = 10π × (a/360)
　a/360 = 1/5 → a = 72°

★ ポイント：おうぎ形は「(中心角)/360 の割合」で円の一部を取り出したもの。弧・面積・中心角のどれか 2 つがわかれば残りが求まる。

⚠ 注意：弧の長さと面積で使う割合 (a/360) は同じ。ただし弧は 2πr に、面積は πr² に掛ける。掛ける相手を取り違えない。`,
