        figureId: 'lf_kmath_32',
        body: `多角形の角の和は公式で一発。図形問題の角度計算の基礎になる。

■ 三角形の内角・外角
　・内角の和 = 180°
　・外角 = 隣り合わない 2 つの内角の和
　　（例：∠A の外角 = ∠B + ∠C）

■ n 角形の内角の和
　内角の和 = 180° ×(n − 2)
　（1 つの頂点から対角線を引くと n−2 個の三角形に分かれる）

┌────────┬────────────┬──────────┐
│ 多角形   │ 内角の和       │ 1 つの内角(正) │
├────────┼────────────┼──────────┤
│ 三角形   │ 180°           │ 60°           │
│ 四角形   │ 360°           │ 90°           │
│ 五角形   │ 540°           │ 108°          │
│ 六角形   │ 720°           │ 120°          │
│ 八角形   │ 1080°          │ 135°          │
└────────┴────────────┴──────────┘

■ 多角形の外角の和（重要）
　どんな多角形でも 外角の和 = 360°（一定！）
　→ 正 n 角形の 1 つの外角 = 360° ÷ n

例）正十角形の 1 つの外角 = 360° ÷ 10 = 36°
　1 つの内角 = 180° − 36° = 144°

■ 正多角形の角の求め方（2 通り）
　方法A：内角の和 180°(n−2) ÷ n
　方法B：180° − (360°÷n)（外角から）
　→ 方法B（外角利用）の方が速いことが多い

★ ポイント：正多角形の 1 つの内角は「180° − 外角」で求めると速い。外角の和は必ず 360° なので、外角 = 360°÷n。

⚠ 注意：内角の和の公式は 180°×(n−2)。n をそのまま掛けて 180°×n としない。四角形なら 180°×2 = 360°。`,
