        body: `等比数列の和は、公式を使えば大量の項でも一瞬で求められる。

■ 等比数列の和の公式
初項a、公比r（r≠1）の等比数列の初項から第n項までの和 Sn
　Sn = a(rⁿ − 1)/(r − 1)

■ 公式の導出（差を作るテクニック）
Sn = a + ar + ar² + … + ar^(n−1) … ①
r×Sn = ar + ar² + … + ar^n … ②
①−②：Sn − rSn = a − ar^n
Sn(1−r) = a(1−r^n)
Sn = a(1−rⁿ)/(1−r)（＝a(rⁿ−1)/(r−1)と同じ値）

■ 具体例
例）初項2、公比3の等比数列の初項から第5項までの和
　Sn = 2(3⁵−1)/(3−1) = 2(243−1)/2 = 242

■ r=2の場合（頻出パターン）
例）1+2+4+8+…+2⁹（第10項まで）の和
　Sn = 1×(2¹⁰−1)/(2−1) = 1024−1 = 1023

■ 等比数列の和の検算（小さい場合で確認）
例）1+2+4=7、公式：a=1,r=2,n=3 → (2³−1)/(2−1)=7 ✓

★ ポイント：r=2のときの和「1+2+4+…+2^(n−1) = 2ⁿ−1」の形は、2進法・倍々ゲームの問題で頻出。暗記しておくと計算が速い。

⚠ 注意：公式の分母は(r−1)。r<1のときは(1−rⁿ)/(1−r)の形の方が符号のミスが少ない。`,
