        body: `異なるものを「順序をつけて」並べる場合の数を求めるのが順列。

■ 順列の公式
異なるn個からr個を選んで1列に並べる場合の数
　nPr = n×(n−1)×(n−2)×…×(n−r+1)　（r個の積）

■ 階乗
n! = n×(n−1)×…×2×1（nから1までのすべての整数の積）
　nPr = n!/(n−r)!

■ 具体例
例）5人から3人を選んで1列に並べる場合の数
　5P3 = 5×4×3 = 60通り

■ 樹形図との対応
5P3の「5」は1番目に選べる人数、「4」は2番目（1人減る）、「3」は3番目。
　1番目：5通り
　2番目：4通り（1番目で使った人を除く）
　3番目：3通り
　積の法則：5×4×3=60

■ n!の値（覚えておくと便利）
　3!=6、4!=24、5!=120、6!=720

★ ポイント：nPrは「1番目の選び方n通り、2番目n−1通り…」と積の法則で考えれば公式を忘れても導ける。

⚠ 注意：nPr の r は「並べる個数」。全部並べる場合はr=nでnPn=n!になる。`,
