        figureId: 'lf_kmath_52',
        body: `平均値だけでは分からない「データの散らばり具合」を数値で表すのが分散・標準偏差。

■ 分散の定義
　分散 = (各データの偏差)²の平均
　偏差 = データの値 − 平均値

■ 分散の計算手順
① 平均値を求める
② 各データの偏差（データ−平均）を求める
③ 偏差を2乗する
④ 2乗した値の平均を求める（これが分散）

例）データ：2, 4, 6, 8, 10
　平均 = (2+4+6+8+10)/5 = 30/5 = 6
　偏差：−4, −2, 0, 2, 4
　偏差の2乗：16, 4, 0, 4, 16
　分散 = (16+4+0+4+16)/5 = 40/5 = 8

■ 標準偏差
　標準偏差 = √分散
例）上のデータの標準偏差 = √8 = 2√2 ≒ 2.83

■ なぜ2乗するのか
偏差をそのまま平均すると、正の偏差と負の偏差が打ち消し合って必ず0になってしまう。2乗することですべて正の値にして、散らばりの大きさを正しく測る。

★ ポイント：分散・標準偏差が大きいほど、データは平均から離れて散らばっている。小さいほど平均付近に集まっている。

⚠ 注意：分散はデータの単位の2乗になってしまう（cmのデータなら分散はcm²）。元の単位に戻すために標準偏差（分散の平方根）を使う。`,
