        body: `平均値が同じでも、標準偏差が違えば「データの性質」はまったく異なる。

■ 平均が同じでも散らばりが違う例
グループA：4, 5, 6, 7, 8（平均6）
グループB：1, 3, 6, 9, 11（平均6）

　グループAの分散：偏差−2,−1,0,1,2 → 2乗4,1,0,1,4 → 分散=10/5=2
　グループBの分散：偏差−5,−3,0,3,5 → 2乗25,9,0,9,25 → 分散=68/5=13.6

　→ 平均は同じ6でも、グループBの方が分散が大きく、ばらつきが大きい

■ テストの得点比較での活用
2つのクラスの平均点が同じでも、標準偏差が小さいクラスは「みんな平均点付近」、標準偏差が大きいクラスは「得意な人と苦手な人の差が大きい」と読み取れる。

■ 標準偏差と四分位範囲の違い
　標準偏差：すべてのデータを使って計算する（外れ値の影響を受けやすい）
　四分位範囲（IQR）：中央の50%だけで計算する（外れ値の影響を受けにくい）

■ 標準偏差が0になる場合
すべてのデータが同じ値のとき、偏差がすべて0になるので分散・標準偏差は0になる。

★ ポイント：平均値だけを見て「同じような分布」と判断するのは危険。標準偏差（またはIQR）を必ず併せて確認する習慣をつける。

⚠ 注意：分散の計算で「偏差の2乗の平均」を「(偏差の平均)の2乗」と混同しないこと。先に2乗してから平均をとる順序を守る。`,
