        heading: '3. 散布図と相関',
        level: 'oyo',
        figureId: 'lf_kmath_53',
        body: `2つの量の関係を視覚化する散布図と、その関係の強さを表す相関について学ぶ。

■ 散布図とは
2つの量（例：身長と体重）を、それぞれx軸・y軸にとり、データを点でプロットした図。

■ 相関の種類
　正の相関：一方が増えると他方も増える傾向（点が右上がりに分布）
　負の相関：一方が増えると他方は減る傾向（点が右下がりに分布）
　相関がない：点がバラバラで規則性が見られない

■ 相関の強さ
点が直線に近い形で集まっているほど「相関が強い」、バラバラに散らばっているほど「相関が弱い」という。

■ 具体例
例）ある学級の10人の「数学のテストの点数」と「理科のテストの点数」を散布図にすると、右上がりの傾向が見られた。
　→ 数学の点数が高い生徒は理科の点数も高い傾向がある（正の相関）

■ 相関関係と因果関係の違い（重要）
2つの量に相関があっても、一方が他方の「原因」であるとは限らない。
例）「アイスクリームの売上」と「水難事故の件数」には正の相関があるが、これはどちらも「気温の上昇」という共通の原因によるものであり、アイスクリームが事故の原因ではない。

★ ポイント：散布図は「点の並び方の傾向」を見る図。相関があるからといって、すぐに因果関係（原因と結果）があると結論づけてはいけない。

⚠ 注意：正の相関・負の相関は「必ずそうなる」という意味ではなく「そういう傾向がある」という統計的な傾向を表す。例外のデータ（外れ値）があっても、全体の傾向で判断する。`,
