        level: 'moshi',
        figureId: 'lf_kmath_54',
        body: `全部を調べる（全数調査）のが難しいとき、一部を調べて全体を推定する標本調査を学ぶ。

■ 全数調査と標本調査
　全数調査：対象全部を調べる（例：国勢調査）
　標本調査：対象の一部（標本）を無作為に抽出して調べ、全体（母集団）を推定する

■ 標本調査が使われる場面
・対象が多すぎて全部調べるのが現実的でない（テレビの視聴率調査など）
・調査に破壊を伴う（電球の寿命調査など、全部調べたら売る商品がなくなる）

■ 標本平均・標本比率から母集団を推定する
例）ある池にいる魚の総数を推定したい。まず100匹を捕獲して印をつけて放す。数日後に80匹を捕獲したところ、印のついた魚が4匹いた。この池の魚の総数を推定せよ。
　標本の中の印の比率 = 4/80 = 1/20
　母集団全体でも同じ比率と仮定すると
　100（印をつけた総数）: 池全体の総数 = 4 : 80
　池全体の総数 = 100×80/4 = 2000匹

■ 無作為抽出の重要性
標本を選ぶときは、偏りがないよう「無作為（ランダム）」に選ぶことが重要。特定の条件の人だけを選ぶと、母集団を正しく推定できない。

■ 標本調査の精度
標本の大きさ（人数・個数）が大きいほど、母集団の推定精度は高くなる傾向がある。

★ ポイント：標本調査の計算は「標本の中の比率＝母集団の中の比率」という比例式に帰着する。魚の推定のような「捕獲・再捕獲法」の計算パターンを覚えておく。

⚠ 注意：標本調査はあくまで「推定」であり、実際の値と完全に一致するとは限らない。標本の選び方に偏りがあると推定が大きくずれる。`,
