        level: 'oyo',
        body: `変化の割合はグラフの傾きと直結する重要な概念。一次関数・二次関数での違いを総復習する。

■ 変化の割合の定義
　変化の割合 = (yの増加量) / (xの増加量)

■ 一次関数の変化の割合
一次関数 y=ax+b の変化の割合は、xの範囲によらず常に a（一定）。

■ 二次関数の変化の割合
二次関数 y=ax² の、xがmからnまで変化するときの変化の割合は
　a(m+n)
　（xの範囲によって値が変わる）

例）y=2x²で、xが1から3まで変化するときの変化の割合
　= 2(1+3) = 8

■ 変化の割合とグラフの傾きの関係
一次関数では変化の割合＝直線の傾き（一定）。
二次関数では変化の割合＝2点を結ぶ直線（割線）の傾きに一致する（区間ごとに変わる）。

■ 変化の割合が等しくなる条件（発展）
例）y=x²で、xがaからa+2まで変化するときの変化の割合が10になるとき、aを求めよ。
　変化の割合 = 1×(a+(a+2)) = 2a+2
　2a+2=10 → a=4

★ ポイント：「変化の割合」は一次関数なら傾きそのもの、二次関数なら区間ごとに変わる平均的な増え方。両者の違いを明確に区別する。

⚠ 注意：二次関数の変化の割合を求める公式 a(m+n) は、必ず「xがmからnまで変化するとき」の形で使う。mとnを取り違えないこと。`,
