        body: `証明問題はパターン化された「型」を身につければ、どんな問題でも安定して書けるようになる。

■ 証明の3段構成
【仮定】問題文で与えられた条件・図から読み取れる事実
　↓
【根拠】仮定から導かれる性質・定理（なぜそう言えるか）
　↓
【結論】証明したい事柄

■ 証明の書き出しのテンプレート
　「△ABCと△DEFにおいて」（対象を明示する）
　　AB=DE …①（〜より）
　　∠B=∠E …②（〜より）
　　BC=EF …③（〜より）
　「①②③より、（合同・相似条件の名前）から　△ABC≡△DEF（または∽）」

■ 根拠として使える代表的な性質
┌──────────────────────────────────────┐
│ 平行線 → 錯角・同位角が等しい                   │
│ 二等辺三角形 → 底角が等しい                     │
│ 円 → 同じ弧に対する円周角が等しい               │
│ 対頂角 → 常に等しい                             │
│ 共通の辺・角 → 「共通だから」で根拠になる       │
└──────────────────────────────────────┘

■ 悪い証明の例と良い証明の例
✗「なんとなく同じ形に見えるから合同」（根拠がない）
○「AB=DE、∠B=∠E、BC=EFがそれぞれ成り立つから、2辺とその間の角がそれぞれ等しく合同」（根拠が明確）

★ ポイント：証明は「思う」「〜のはず」ではなく「等しい」「成り立つ」と断定する文体で書く。根拠となる定理の名前（錯角、円周角の定理など）を必ず添える。

⚠ 注意：証明の最後は必ず「よって、（結論）」で締めくくる。根拠を並べただけで終わらせず、結論を明記する。`,
