        body: `「AならばB」という命題に対して、「BならばA」を逆の命題という。逆が必ずしも成り立つとは限らない。

■ 逆の命題の作り方
命題「Aならば B」の逆は「Bならば A」

例）命題「正方形ならばひし形である」
　逆：「ひし形ならば正方形である」

■ 逆の真偽を確認する
　元の命題「正方形ならばひし形」は真（正方形は4辺が等しいのでひし形の条件を満たす）
　逆の命題「ひし形ならば正方形」は偽（ひし形は角が直角とは限らない）

■ 反例の見つけ方
逆の命題が偽であることを示すには、条件を満たすが結論が成り立たない具体例（反例）を1つ挙げればよい。

例）「ひし形ならば正方形」の反例
　1辺の長さがすべて等しいが、角が90°でないひし形（ひしゃげた形）

■ 図形の性質での逆の命題の例
┌──────────────────────────────────────┐
│ 「二等辺三角形なら底角が等しい」（真）→ 逆も真   │
│ 「四角形の対角線が垂直に交わるならひし形」（偽） │
│　→ 反例：たこ形（対角線は垂直だが4辺は等しくない）│
└──────────────────────────────────────┘

★ ポイント：ある命題が真であっても、その逆が真とは限らない。図形の性質を学ぶときは「逆は成り立つか」を常に確認する習慣をつける。

⚠ 注意：反例は「条件は満たすが結論が成り立たない具体例をたった1つ」示せば十分。反例が見つかった時点でその命題は偽と確定する。`,
