        heading: '5. 背理法による証明',
        level: 'moshi',
        body: `直接証明するのが難しい命題は、「結論を否定して矛盾を導く」背理法が有効な場合がある。

■ 背理法の考え方
証明したい結論の否定を仮定し、そこから矛盾（すでにわかっている事実と食い違う結果）を導く。矛盾が起きた以上、否定した仮定が誤りであり、もとの結論が正しいとわかる。

■ 背理法の基本手順
① 結論を否定して仮定する
② その仮定から論理的に式を進める
③ 矛盾（あり得ない結果）を導く
④ 「矛盾するので、仮定は誤り。よって元の結論が正しい」と結ぶ

■ 具体例（√2が無理数であることの証明・有名な背理法）
√2が有理数であると仮定する。
　√2 = n/m（n, mは互いに素な自然数）とおける
　両辺を2乗：2 = n²/m² → n² = 2m²
　→ n²は偶数 → nは偶数（nを2kとおける）
　(2k)² = 2m² → 4k² = 2m² → m² = 2k²
　→ m²は偶数 → mも偶数
　→ nとmがともに偶数になり、「互いに素」という仮定に矛盾
　よって、√2は有理数ではない（無理数である）

■ 中学範囲での背理法の使いどころ
「ある数が無理数であることの証明」「ある図形の性質が成り立たないことの証明」など、直接証明が難しい場面で背理法が使われる。

★ ポイント：背理法は「結論を否定してみて、矛盾が起きることを示す」という逆転の発想。直接証明の道筋が見えないときの強力な選択肢として持っておく。

⚠ 注意：背理法では、最終的にどんな事実と矛盾したのかを明確に書く（「互いに素であることに矛盾する」など）。矛盾の内容を書かずに終えると証明として不完全になる。`,
